	/** 
	 * jumpstart the process by instantiating2 Deal
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		dealId = DealService.getDealInstance()
		.createDeal( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		DealService.getDealInstance()
				.createDeal( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.dealSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Deal : " + successValue.getDealId());
							  if (successValue.getDealId().equals(dealId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfDealList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Deal test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on deal consumed")
					);
			subscriber.dealSubscribe( dealId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Deal : " + successValue.getDealId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfDealList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on deal for dealId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Deal. 
	 */
	protected Deal read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Deal" );

		Deal entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Deal with primary key" );
		msg.append( dealId );
		
		DealFetchOneSummary fetchOneSummary = new DealFetchOneSummary( dealId );

		try {
			entity = DealService.getDealInstance().getDeal( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Deal " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Deal.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Deal." );

		StringBuilder msg = new StringBuilder( "Failed to update a Deal : " );        
		Deal entity = read();
		UpdateDealCommand command = generateUpdateCommand();
		command.setDealId(entity.getDealId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Deal." );

			// for use later on...
			dealId = entity.getDealId();

			DealService proxy = DealService.getDealInstance();  

			proxy.updateDeal( command ).get();

			LOGGER.info( "-- Successfully saved Deal - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + dealId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Deal.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Deal." );

		Deal entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Deal with id " + dealId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Deal with id " + dealId );

			throw e;
		}

		try{
			DealService.getDealInstance().delete( new DeleteDealCommand( entity.getDealId() ) ).get();
			LOGGER.info( "-- Successfully deleted Deal with id " + dealId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Deal with id " + dealId );

			throw e;
		}
	}

	/**
	 * get all Deals.
	 */
	protected List<Deal> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Deals:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Deal : " );        
		List<Deal> collection  = new ArrayList<>();

		try {
			// call the static get method on the DealService
			collection = DealService.getDealInstance().getAllDeal();
			assertNotNull( collection, "An Empty collection of Deal was incorrectly returned.");
			
			// Now print out the values
			Deal entity = null;            
			Iterator<Deal> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getDealId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

